$(function () {
    // Capitalize First Letter
    $('.upper').on('keyup', function () {
        let start = this.selectionStart;
        let end = this.selectionEnd;
        this.value = this.value.charAt(0).toUpperCase() + this.value.slice(1);
        this.setSelectionRange(start, end); // Mempertahankan kursor di tempatnya semula
    });

    // Format input angka
    $('.angka').on('input', function () {
        let match = this.value.replace(/[^0-9.]/g, '').match(/^\d*\.?\d{0,2}/);
        this.value = match ? match[0] : '';
    });

    // Format input rupiah
    $('.rupiah').on('input change', function () {
        $(this).val(CirebonwebFormat.Rupiah($(this).val(), false));
    });
});

/**
 * Objek global untuk mengelola fungsionalitas format.
 * Mengandung fungsi-fungsi helper untuk memformat data seperti tanggal dan angka.
 */
const CirebonwebFormat = {
    /**
     * Memformat tanggal dari YYYY-MM-DD atau DD-MM-YYYY menjadi DD-MM-YYYY.
     *
     * Contoh:
     * { targets: [10, 11], render: function (data, type, row) { return CirebonwebFormat.Tanggal(data) } },
     * $('#order_tgl').val(CirebonwebFormat.Tanggal(today));
     * 
     * @param {string} value String tanggal yang akan diformat.
     * @returns {string} Tanggal yang diformat atau string asli jika format tidak dikenali.
     */
    Tanggal: function (value, mode = 'auto') {
        if (!value) return '-';

        const dateObj = new Date(value);

        // Diubah menjadi 2-digit agar menghasilkan angka (09), bukan teks (Sep)
        const optionsDate = {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
        };

        const optionsTime = {
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false
        };

        // Mengubah format bawaan id-ID (dd/mm/yyyy) menjadi dd-mm-yyyy
        const tanggal = dateObj.toLocaleDateString('id-ID', optionsDate).replace(/\//g, '-');
        const waktu = dateObj.toLocaleTimeString('id-ID', optionsTime);

        if (mode === 'tanggal') return tanggal;

        if (mode === 'auto') {
            // Regex disesuaikan agar mendeteksi string tanggal murni
            if (/^\d{4}-\d{2}-\d{2}/.test(value)) {
                return tanggal;
            }
        }

        return `${tanggal} ${waktu}`;
    },

    /**
     * Mengisi datepicker dari tanggal format MySQL.
     *
     * Contoh:
     * CirebonwebFormat.isoTanggal('promo_awal', '2026-06-04');
     *
     * Hasil:
     * #promo_awal_tgl = 04-06-2026
     * #promo_awal     = 2026-06-04
     *
     * @param {string} id Base ID tanpa suffix _tgl
     * @param {string} mysqlDate Format YYYY-MM-DD
     */
    isoTanggal: function (id, mysqlDate) {
        if (!mysqlDate) return;

        const date = $.datepicker.parseDate('yy-mm-dd', mysqlDate);
        const $displayInput = $('#' + id + '_tgl').length
            ? $('#' + id + '_tgl')
            : $('#' + id);

        $displayInput.datepicker('setDate', date);
        if ($('#' + id).attr('type') === 'hidden') {
            $('#' + id).val(mysqlDate);
        }
    },

    /**
     * Mengubah tanggal tampilan DD-MM-YYYY menjadi format tanggal MySQL.
     *
     * @param {string} value Tanggal dalam format DD-MM-YYYY.
     * @returns {string} Tanggal dalam format YYYY-MM-DD atau string kosong jika tidak valid.
     */
    mysqlTanggal: function (value) {
        if (!value) return '';

        try {
            const date = $.datepicker.parseDate('dd-mm-yy', value);
            return $.datepicker.formatDate('yy-mm-dd', date);
        } catch (error) {
            return '';
        }
    },

    /**
     * Memformat angka menjadi format Rupiah (dengan titik sebagai pemisah ribuan).
     *
     * @param {string|number} value Angka yang akan diformat.
     * @returns {string} String dengan format Rupiah.
     */
    Rupiah: function (value) {
        // Konversi ke string dan hapus semua karakter non-digit
        const stringValue = String(value).replace(/\D/g, '');
        // Tambahkan titik sebagai pemisah ribuan
        return stringValue.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    },

    /**
     * Menghilangkan format Rupiah (menghapus titik dan karakter non-digit lainnya).
     *
     * @param {string} value String dengan format Rupiah.
     * @returns {string} String yang hanya berisi digit.
     */
    unRupiah: function (value) {
        return String(value).replace(/\D/g, '');
    },

    /**
     * Memformat angka ke format lokal (ID) dengan pemisah ribuan dan desimal.
     * Ini adalah cara yang lebih baik daripada formatRupiah karena menggunakan API bawaan browser.
     *
     * @param {number} value Angka yang akan diformat.
     * @returns {string} String angka yang diformat secara lokal.
     */
    lokasiRupiah: function (value) {
        if (typeof value !== 'number' || isNaN(value)) return '';
        return value.toLocaleString('id-ID');
    },

    /**
     * Memformat angka desimal secara dinamis dengan separator titik (.)
     * Menghapus angka 0 yang tidak diperlukan di belakang desimal.
     * 
     * Contoh:
     * 1.00 -> "1"
     * 1.20 -> "1.2"
     * 1.23 -> "1.23"
     */
    Desimal: function (value) {
        if (value === undefined || value === null || value === '') return '0';

        // 1. Paksa konversi ke tipe data Number. 
        // JS akan otomatis membuang trailing zeros (1.20 menjadi 1.2, 1.00 menjadi 1)
        let parsed = Number(value);

        // Jika input bukan angka yang valid, kembalikan '0'
        if (isNaN(parsed)) return '0';

        // 2. Kembalikan dalam bentuk string desimal bertitik
        return parsed.toString();
    }
};
